```go
package main

import (
	"encoding/json"
	"fmt"
)

type User struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
}

func main() {
	data, err := json.Marshal(User{ID: 7, Name: "Mina"})
	if err != nil {
		panic(err)
	}
	var decoded User
	if err := json.Unmarshal(data, &decoded); err != nil {
		panic(err)
	}
	fmt.Printf("%s -> %+v\n", data, decoded)
}
```
The destination is a pointer, and both conversion errors are handled before the values are used.

```go
package main

import (
	"encoding/json"
	"errors"
	"fmt"
)

type Node struct {
	Value int   `json:"value"`
	Next  *Node `json:"next,omitempty"`
}

func main() {
	n := &Node{Value: 1}
	n.Next = n
	_, err := json.Marshal(n)
	var valueErr *json.UnsupportedValueError
	fmt.Println(err != nil, errors.As(err, &valueErr))
}
```
The self-reference is legal Go but not a finite JSON tree, so Marshal returns an UnsupportedValueError.

```go
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

type Input struct {
	Name string `json:"name"`
}

func decodeOne(text string) error {
	dec := json.NewDecoder(strings.NewReader(text))
	dec.DisallowUnknownFields()
	var in Input
	if err := dec.Decode(&in); err != nil {
		return err
	}
	var extra any
	if err := dec.Decode(&extra); err != io.EOF {
		if err == nil {
			return fmt.Errorf("more than one JSON value")
		}
		return fmt.Errorf("trailing data: %w", err)
	}
	fmt.Println(in.Name)
	return nil
}

func main() {
	if err := decodeOne(`{"name":"Ada"}`); err != nil {
		panic(err)
	}
	fmt.Println(decodeOne(`{"name":"Ada"} {}`) != nil)
}
```
The second call is the single-document check; DisallowUnknownFields does not perform that job.
